export function getRandomText(category = null, difficulty = null) {
  let filtered = texts;
  if (category) {
    filtered = filtered.filter(t => t.category === category);
  }
  if (difficulty) {
    filtered = filtered.filter(t => t.difficulty === difficulty);
  }
  if (filtered.length === 0) return texts[Math.floor(Math.random() * texts.length)];
  return filtered[Math.floor(Math.random() * filtered.length)];
}

export function getTextById(id) {
  return texts.find(t => t.id === id) || null;
}

export function getTextsByCategory(category) {
  return texts.filter(t => t.category === category);
}

export function getTextForDuration(durationSec, category = null) {
  let minChars = 0;
  let maxChars = Infinity;
  
  if (durationSec === 15) {
    minChars = 150;
    maxChars = 320;
  } else if (durationSec === 30) {
    minChars = 250;
    maxChars = 400;
  } else if (durationSec === 60) {
    minChars = 300;
    maxChars = 500;
  } else if (durationSec === 120) {
    minChars = 350;
    maxChars = 650;
  }

  let filtered = texts;
  if (category && category !== 'all') {
    filtered = filtered.filter(t => t.category === category);
  }

  const lengthFiltered = filtered.filter(t => t.charCount >= minChars && t.charCount <= maxChars);
  if (lengthFiltered.length > 0) {
    return lengthFiltered[Math.floor(Math.random() * lengthFiltered.length)];
  }

  if (filtered.length === 0) return getRandomText(category);
  return filtered[Math.floor(Math.random() * filtered.length)];
}
